32:   bool finite_service = false;
33:   bool progressive_wakeup = false;
34:   mode selected_mode = mode::LEGACY;
35:   unsigned pib_entries = 8;
36:   unsigned tag_banks = 4;
37:   unsigned tag_requests_per_bank_per_cycle = 1;
38:   unsigned tag_requests_per_cycle = 4;
39:   unsigned coalescer_threads_per_cycle = 32;
40:   unsigned logical_sets = 32;
41:   unsigned logical_ways = 4;
42:   unsigned physical_lines = 640;
43:   unsigned allocation_width = 4;
