516: // Whole-line OO-DTC model.  Unlike io_frontend, physical-line lifetime is
517: // protected by one Ref per live coalesced 128B reference, and any oldest-ready
518: // PIB entry may retire.  It has no dependency on conventional L1D MSHRs.
519: class oo_frontend {
520:  public:
521:   explicit oo_frontend(config cfg)
522:       : m_cfg(cfg),
523:         m_tags(cfg.logical_sets * cfg.logical_ways),
524:         m_phys(cfg.physical_lines),
525:         m_slots(cfg.oo_pib_entries) {
526:     check_tag_hash_bankrow(cfg.tag_hash_bankrow,
527:                            cfg.selected_mode == mode::PAPER_OO,
528:                            cfg.finite_service, cfg.logical_sets, cfg.tag_banks);
529:     check_progressive_wakeup_mode(cfg.progressive_wakeup,
530:         static_cast<unsigned>(cfg.selected_mode), cfg.finite_service);
531:     assert(cfg.logical_sets && cfg.logical_ways && cfg.physical_lines);
532:     assert(cfg.allocation_width && cfg.oo_pib_entries);
533:     assert(cfg.ref_count_bits && cfg.ref_count_bits < 32);
534:     assert(cfg.tag_banks && cfg.tag_requests_per_bank_per_cycle &&
535:            cfg.tag_requests_per_cycle);
536:   }
537: 
538:   void begin_cycle(uint64_t cycle) {
539:     if (cycle == m_cycle) return;
540:     m_cycle = cycle;
541:     m_allocations_this_cycle = 0;
542:   }
543: 
544:   bool admit(uint64_t uid) {
545:     if (find_entry(uid)) return true;
546:     if (m_entries.size() >= m_cfg.oo_pib_entries) return false;
547:     unsigned slot = 0;
548:     for (; slot < m_slots.size(); ++slot)
549:       if (!m_slots[slot].active) break;
550:     assert(slot < m_slots.size());
551:     slot_state &state = m_slots[slot];
552:     state.active = true;
553:     state.uid = uid;
554:     ++state.generation;
555:     m_entries.push_back({uid, slot, state.generation, {}, 0});
556:     assert_shadow_refs();

571:   bool try_serve_tag(uint64_t cycle, uint64_t address) {
572:     if (cycle != m_tag_cycle) {
573:       m_tag_cycle = cycle;
574:       std::fill(m_tag_requests_this_cycle.begin(),
575:                 m_tag_requests_this_cycle.end(), 0);
576:       m_total_tag_requests_this_cycle = 0;
577:     }
578:     const unsigned set = tag_set(address);
579:     const unsigned bank = set % m_cfg.tag_banks;
580:     if (m_total_tag_requests_this_cycle >= m_cfg.tag_requests_per_cycle ||
581:         m_tag_requests_this_cycle[bank] >=
582:             m_cfg.tag_requests_per_bank_per_cycle) {
583:       ++m_tag_conflicts;
584:       return false;
585:     }
586:     ++m_total_tag_requests_this_cycle;
587:     ++m_tag_requests_this_cycle[bank];
588:     ++m_tag_requests;
589:     return true;

637:   io_access_result access(uint64_t cycle, uint64_t uid, uint64_t address) {
638:     begin_cycle(cycle);
639:     entry *owner = find_entry(uid);
640:     assert(owner);
641:     const uint64_t line = address & ~(kLogicalLineBytes - 1);
642:     tag_entry *tag = find_tag(line);
643:     if (tag) {
644:       attach_reference(*owner, tag->physical);
645:       ++(m_phys[tag->physical.id].ready ? m_valid_hits : m_pending_hits);
646:       assert_shadow_refs();
647:       return {m_phys[tag->physical.id].ready ? io_access_kind::VALID_HIT
648:                                               : io_access_kind::PENDING_HIT,
649:               tag->physical};
650:     }
651:     if (m_allocations_this_cycle >= m_cfg.allocation_width) {
652:       ++m_allocation_width_limited_events;
653:       return {io_access_kind::NO_FREE_LINE, {}};
654:     }
655: 
656:     tag_entry *victim = select_victim(line);
657:     int free_id = find_free_physical();
658:     const bool can_reclaim_victim =
659:         victim->valid && m_phys[victim->physical.id].ref_count == 0;
660:     if (free_id < 0 && !can_reclaim_victim) {
661:       ++m_no_free_physical_events;
662:       return {io_access_kind::NO_FREE_LINE, {}};
663:     }
664:     if (victim->valid) {
665:       physical_line &old = m_phys[victim->physical.id];
666:       assert(old.allocated && old.tag_valid);
667:       old.tag_valid = false;
668:       if (m_cfg.finite_service) m_service_map_loss[victim->physical.id] = cycle;
669:       ++m_tag_evictions;
670:       if (old.ref_count == 0) {
671:         release(victim->physical);
672:         ++m_immediate_reclaims;
673:       } else {
674:         ++m_deferred_reclaims;
675:       }
676:     }
677:     if (free_id < 0) free_id = find_free_physical();
678:     assert(free_id >= 0);
679:     physical_line &physical = m_phys[free_id];
680:     physical.allocated = true;
681:     physical.ready = false;
682:     if (m_cfg.progressive_wakeup) {
683:       physical.data_ready = false;
684:       physical.return_cycle = UINT64_MAX;
685:       physical.first_notify_cycle = physical.last_notify_cycle = UINT64_MAX;
686:       physical.notified = physical.late_merges = 0;
687:     }
688:     physical.tag_valid = true;
689:     physical.ref_count = 0;
690:     physical.waiters.clear();
691:     physical_identity identity{static_cast<unsigned>(free_id),
692:                                ++physical.generation};
693:     *victim = {true, line, identity, ++m_lru_clock};
694:     attach_reference(*owner, identity);
695:     ++m_allocations_this_cycle;
696:     ++m_new_misses;
697:     assert_shadow_refs();
698:     return {io_access_kind::NEW_MISS, identity};

801:   bool retire_one_ready(uint64_t cycle, uint64_t *retired_uid = nullptr) {
802:     if (cycle == m_retire_cycle) return false;  // frozen width: one/cycle
803:     auto selected = m_entries.end();
804:     for (auto it = m_entries.begin(); it != m_entries.end(); ++it) {
805:       if (entry_ready(*it)) {
806:         selected = it;
807:         break;
808:       }
809:     }
810:     if (selected == m_entries.end()) return false;
811:     bool older_unready = false;
812:     for (auto it = m_entries.begin(); it != selected; ++it)
813:       older_unready |= !entry_ready(*it);
814:     if (older_unready) ++m_out_of_order_retires;
815:     for (const physical_identity identity : selected->references) {
816:       physical_line &physical = m_phys[identity.id];
817:       assert(physical.allocated && physical.generation == identity.generation &&
818:              physical.ref_count);
819:       --physical.ref_count;
820:       if (!physical.tag_valid && physical.ref_count == 0) {
821:         release(identity);
822:         ++m_final_ref_reclaims;
823:       }
824:     }
825:     m_slots[selected->slot].active = false;
826:     if (retired_uid) *retired_uid = selected->uid;
827:     m_entries.erase(selected);
828:     m_retire_cycle = cycle;
829:     ++m_retires;
830:     assert_shadow_refs();
831:     return true;
832:   }
833: 
834:   // M4 supplies an eligibility-filtered UID when source-backed fence
835:   // ordering constrains OO retirement. The frozen one-retirement/cycle width
836:   // and OOO accounting remain identical to retire_one_ready().
837:   bool retire_ready_uid(uint64_t cycle, uint64_t uid) {
838:     if (cycle == m_retire_cycle) return false;
839:     auto selected = m_entries.end();
840:     for (auto it = m_entries.begin(); it != m_entries.end(); ++it)
841:       if (it->uid == uid) { selected = it; break; }
842:     if (selected == m_entries.end() || !entry_ready(*selected)) return false;
843:     bool older_unready = false;
844:     for (auto it = m_entries.begin(); it != selected; ++it)
845:       older_unready |= !entry_ready(*it);
846:     if (older_unready) ++m_out_of_order_retires;
847:     for (const physical_identity identity : selected->references) {
848:       physical_line &physical = m_phys[identity.id];
849:       assert(physical.allocated && physical.generation == identity.generation &&
850:              physical.ref_count);
851:       --physical.ref_count;
852:       if (!physical.tag_valid && physical.ref_count == 0) {
853:         release(identity);
854:         ++m_final_ref_reclaims;
855:       }
856:     }
857:     m_slots[selected->slot].active = false;
858:     m_entries.erase(selected);
859:     m_retire_cycle = cycle;
860:     ++m_retires;
861:     assert_shadow_refs();
862:     return true;

1064:   void attach_reference(entry &owner, physical_identity identity) {
1065:     if (has_reference(owner, identity)) return;
1066:     physical_line &physical = m_phys[identity.id];
1067:     assert(physical.allocated && physical.generation == identity.generation);
1068:     const uint64_t max_ref_count = (1ULL << m_cfg.ref_count_bits) - 1;
1069:     assert(physical.ref_count < max_ref_count);
1070:     ++physical.ref_count;
1071:     owner.references.push_back(identity);
1072:     if (!physical.ready) {
1073:       if (m_cfg.progressive_wakeup && physical.data_ready) {
1074:         ++physical.late_merges;
1075:         ++m_late_merges;
1076:       }
1077:       physical.waiters.push_back({owner.slot, owner.slot_generation});
1078:       ++owner.pending_dependencies;
1079:     }
1080:   }
1081:   bool entry_ready(const entry &owner) const {
1082:     if (owner.pending_dependencies || owner.external_dependencies) return false;
1083:     for (const physical_identity identity : owner.references)
1084:       if (!fill_identity_matches(identity) ||
1085:           !(m_cfg.progressive_wakeup ? m_phys[identity.id].data_ready
1086:                                     : m_phys[identity.id].ready))
1087:         return false;

1090:   unsigned tag_set(uint64_t address) const {
1091:     return logical_tag_set(address, m_cfg.logical_sets, m_cfg.tag_hash_bankrow);
1092:   }
1093:   tag_entry *find_tag(uint64_t line) {
1094:     const unsigned set = tag_set(line);
1095:     for (unsigned way = 0; way < m_cfg.logical_ways; ++way) {
1096:       tag_entry &tag = m_tags[set * m_cfg.logical_ways + way];
1097:       if (tag.valid && tag.line == line) {
1098:         tag.lru = ++m_lru_clock;
1099:         return &tag;
1100:       }
1101:     }
1102:     return nullptr;
1103:   }
1104:   tag_entry *select_victim(uint64_t line) {
1105:     const unsigned set = tag_set(line);
1106:     tag_entry *victim = &m_tags[set * m_cfg.logical_ways];
1107:     for (unsigned way = 0; way < m_cfg.logical_ways; ++way) {
1108:       tag_entry &tag = m_tags[set * m_cfg.logical_ways + way];
1109:       if (!tag.valid) return &tag;
1110:       if (tag.lru < victim->lru) victim = &tag;
1111:     }
1112:     return victim;
1113:   }
1114:   int find_free_physical() {
1115:     for (unsigned offset = 0; offset < m_phys.size(); ++offset) {
1116:       const unsigned id = (m_rr_next + offset) % m_phys.size();
1117:       if (!m_phys[id].allocated) {
1118:         m_rr_next = (id + 1) % m_phys.size();
1119:         return id;
1120:       }
1121:     }
1122:     return -1;
1123:   }
1124:   void release(physical_identity identity, uint64_t release_cycle = UINT64_MAX) {
1125:     physical_line &physical = m_phys[identity.id];
1126:     assert(physical.allocated && physical.generation == identity.generation &&
1127:            !physical.tag_valid && !physical.ref_count);
1128:     if (m_cfg.finite_service) {
1129:       const auto lost = m_service_map_loss.find(identity.id);
1130:       assert(lost != m_service_map_loss.end());
1131:       const uint64_t now = release_cycle == UINT64_MAX
1132:                                ? m_service_cycle : release_cycle;
1133:       assert(now >= lost->second);
1134:       m_service_map_loss_sum += now - lost->second;
1135:       ++m_service_map_loss_count;
1136:       m_service_map_loss.erase(lost);
1137:     }
1138:     if (m_cfg.progressive_wakeup) {
1139:       assert(physical.ready && physical.data_ready && physical.waiters.empty());
1140:       for (const auto &pending : m_service_returns)
1141:         assert(pending.physical.id != identity.id ||
1142:                pending.physical.generation != identity.generation);
1143:       physical.data_ready = false;
1144:     }
1145:     physical.allocated = false;
1146:     physical.ready = false;
1147:     physical.waiters.clear();

1: #ifndef DTC_L1_TAG_INDEX_H
2: #define DTC_L1_TAG_INDEX_H
