11: inline void register_tag_hash_bankrow_option(option_parser_t parser,
12:                                              bool *enabled) {
13:   option_parser_register(parser, "-gpgpu_dtc_l1_tag_hash_bankrow", OPT_BOOL,
14:                          enabled,
15:                          "Opt-in fixed bank-preserving XOR Tag row index; "
16:                          "PAPER_OO whole-line finite V1 only", "0");
17: }
18: 
19: inline void check_tag_hash_bankrow(bool enabled, bool paper_oo, bool finite,
20:                                    unsigned sets, unsigned banks) {
21:   if (!enabled) return;  // K0 keeps every old geometry and recency rule.
22:   const char *reason = nullptr;
23:   if (!paper_oo)
24:     reason = "TAG_HASH_BANKROW_PAPER_OO_ONLY_STOP";
25:   else if (!finite)
26:     reason = "TAG_HASH_BANKROW_FINITE_V1_REQUIRED_STOP";
27:   else if (banks != 4 || sets < 4 || (sets & (sets - 1)) || sets % 4)
28:     reason = "TAG_HASH_BANKROW_UNSUPPORTED_GEOMETRY_STOP";
29:   if (reason) {
30:     std::fprintf(stderr, "%s: sets=%u banks=%u\n", reason, sets, banks);
31:     std::abort();
32:   }
33: }
34: 
35: // Constructor validation guarantees the ON geometry. The shifts/mask are
36: // fixed wiring for a configured S=2^s; row selection uses s-2 parallel XORs.
37: // Complete logical line addresses remain stored/compared by the caller.
38: inline unsigned logical_tag_set(uint64_t address, unsigned sets, bool hash) {
39:   if (!hash) return static_cast<unsigned>((address / 128) % sets);
40:   unsigned s = 0;
41:   for (unsigned n = sets; n > 1; n >>= 1) ++s;
42:   const uint64_t line = address >> 7;
43:   const unsigned row = static_cast<unsigned>(
44:       ((line >> 2) ^ (line >> s)) & ((sets / 4) - 1));
45:   return 4 * row + static_cast<unsigned>(line & 3);
46: }
47: 
