3349: bool ldst_unit::dtc_l1_oo_memory_cycle(
3350:     warp_inst_t &inst, mem_stage_stall_type &stall_reason,
3351:     mem_stage_access_type &access_type) {
3352:   const unsigned uid = inst.get_uid();
3353:   dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(uid);
3354:   if (!entry) {
3355:     const bool admitted = dtc_l1_sector_oo_active()
3356:                              ? m_dtc_l1_sector_frontend->admit(uid)
3357:                              : m_dtc_l1_oo_frontend->admit(uid);
3358:     if (!admitted) {
3359:       stall_reason = BK_CONF;
3360:       access_type = G_MEM_LD;
3361:       return false;
3362:     }
3363:     m_dtc_l1_oo_pib.push_back({inst, dtc_l1_io_line_references(inst), 0});
3364:     m_dtc_l1_oo_pib.back().owner_kernel_uid = dtc_l1_owner_kernel_uid();
3365:     entry = &m_dtc_l1_oo_pib.back();
3366:     assert(!entry->references.empty());
3367:     dtc_l1_r4c0_record_pib(entry->inst, entry->references, "OO");
3368:   }
3369:   if (entry->next_reference < entry->references.size()) {
3370:     const dtc_l1::line_reference reference =
3371:         entry->references[entry->next_reference];
3372:     const unsigned long long cycle =
3373:         m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3374:     // Modern sector mode can enqueue up to four candidates for one logical
3375:     // reference.  Reserve that maximum before frontend mutation so its
3376:     // bounded candidate queue cannot overflow after allocation.
3377:     const size_t lower_candidate_reservation =
3378:         dtc_l1_sector_oo_active()
3379:             ? m_dtc_l1_sector_frontend->prospective_new_requests(
3380:                   reference.line_address, reference.sector_mask)
3381:             : (m_dtc_l1_oo_frontend->will_new_miss(reference.line_address)
3382:                    ? 1
3383:                    : 0);
3384:     if (m_dtc_l1_oo_lower_create_queue.size() +
3385:             lower_candidate_reservation >
3386:         m_config->dtc_l1_oo_pib_entries) {
3387:       ++m_dtc_l1_oo_lower_create_queue_full_stalls;
3388:       stall_reason = BK_CONF;
3389:       access_type = G_MEM_LD;
3390:       return false;
3391:     }
3392:     const bool prior_grant = dtc_l1_finite_service_active() &&
3393:                             entry->service.tag_grant_cycle != UINT64_MAX;
3394:     const bool tag_served = prior_grant || (dtc_l1_sector_oo_active()
3395:                                 ? m_dtc_l1_sector_frontend->try_serve_tag(
3396:                                       cycle, reference.line_address)
3397:                                 : m_dtc_l1_oo_frontend->try_serve_tag(
3398:                                       cycle, reference.line_address));
3399:     if (!tag_served) {
3400:       stall_reason = BK_CONF;
3401:       access_type = G_MEM_LD;
3402:       return false;
3403:     }
3404:     if (dtc_l1_finite_service_active() &&
3405:         (!prior_grant || !entry->service.tag_can_commit(cycle))) {
3406:       if (!prior_grant) entry->service.tag_grant_cycle = cycle;
3407:       stall_reason = COAL_STALL;
3408:       access_type = G_MEM_LD;
3409:       return false;
3410:     }
3411:     if (dtc_l1_sector_oo_active()) {
3412:       const dtc_l1::sector_oo_frontend::access_result result =
3413:           m_dtc_l1_sector_frontend->access(cycle, uid, reference.line_address,
3414:                                             reference.sector_mask);
3415:       if (result.kind == dtc_l1::io_access_kind::NO_FREE_LINE) {
3416:         stall_reason = BK_CONF;
3417:         access_type = G_MEM_LD;
3418:         return false;
3419:       }
3420:       for (unsigned sector = 0; sector < dtc_l1::kSectorsPerLogicalLine;
3421:            ++sector) {
3422:         const uint8_t sector_bit = static_cast<uint8_t>(1U << sector);
3423:         if (!(result.new_request_mask & sector_bit)) continue;
3424:         assert(m_dtc_l1_oo_lower_create_queue.size() <
3425:                m_config->dtc_l1_oo_pib_entries);
3426:         m_dtc_l1_oo_lower_create_queue.push_back(
3427:             {uid, result.physical, reference.line_address, sector_bit});
3428:       }
3429:     } else {
3430:       const dtc_l1::io_access_result result =
3431:           m_dtc_l1_oo_frontend->access(cycle, uid, reference.line_address);
3432:       if (result.kind == dtc_l1::io_access_kind::NO_FREE_LINE) {
3433:         stall_reason = BK_CONF;
3434:         access_type = G_MEM_LD;
3435:         return false;
3436:       }
3437:       if (result.kind == dtc_l1::io_access_kind::NEW_MISS) {
3438:         assert(m_dtc_l1_oo_lower_create_queue.size() <
3439:                m_config->dtc_l1_oo_pib_entries);
3440:         m_dtc_l1_oo_lower_create_queue.push_back(
3441:             {uid, result.physical, reference.line_address, 0xF});
3442:       }
3443:     }
3444:     ++entry->next_reference;
3445:     if (dtc_l1_finite_service_active()) {
3446:       const bool has_next = entry->next_reference < entry->references.size();
3447:       entry->service.prefetch_next_tag(*m_dtc_l1_oo_frontend, cycle, has_next,
3448:           has_next ? entry->references[entry->next_reference].line_address : 0);
3449:     }
3450:   }
3451:   if (entry->next_reference != entry->references.size()) {
3452:     stall_reason = COAL_STALL;
3453:     access_type = G_MEM_LD;
3454:     return false;
3455:   }
3456:   while (!inst.accessq_empty()) inst.accessq_pop_back();

3461:   if (!dtc_l1_paper_oo_active()) return;
3462:   const unsigned long long cycle =
3463:       m_core->get_gpu()->gpu_sim_cycle + m_core->get_gpu()->gpu_tot_sim_cycle;
3464:   if (!m_dtc_l1_oo_lower_create_queue.empty() &&
3465:       (!dtc_l1_finite_service_active() || m_dtc_service_create.available(cycle)) &&
3466:       m_core->get_gpu()->dtc_l1_try_acquire_lower_request()) {
3467:     if (dtc_l1_finite_service_active()) m_dtc_service_create.commit(cycle);
3468:     const dtc_l1_oo_lower_candidate candidate =
3469:         m_dtc_l1_oo_lower_create_queue.front();
3470:     dtc_l1_oo_pib_entry *entry = dtc_l1_oo_find_entry(candidate.inst_uid);
3471:     assert(entry);
3472:     mem_access_byte_mask_t byte_mask;
3473:     mem_access_sector_mask_t sector_mask;
3474:     uint64_t request_address = candidate.line_address;
3475:     unsigned request_size = dtc_l1::kLogicalLineBytes;
